COMMENT ON COLUMN rail_section.id IS '主键';
COMMENT ON COLUMN rail_section.section_id IS '区段 ID，全局唯一';
COMMENT ON COLUMN rail_section.created_at IS '注册时刻，UTC 毫秒';

